index 479a3ca..81f69c2 100644
--- a/crates/ocean-agent/src/session/mod.rs
+++ b/crates/ocean-agent/src/session/mod.rs
@@ -507,6 +507,266 @@ pub fn detail(config_dir: &Path, id: SessionId) -> anyhow::Result<SessionDetail>
     Ok(session_detail(session))
