   29	/// `GET /v1/agent/history/search` searches only ocean-agent's persisted,
   30	/// display-ready transcript projection. The blocking file scan runs off the
   31	/// async executor and cannot invoke a provider or embedding service.
   32	pub(super) async fn history_search(
   33	    State(state): State<AppState>,
   34	    Query(params): Query<HistorySearchQuery>,
   35	) -> (StatusCode, Json<HistorySearchResponse>) {
   36	    let query = params.q.unwrap_or_default();
   37	    if query.trim().is_empty() {
   38	        return response(
   39	            StatusCode::BAD_REQUEST,
   40	            query,
   41	            Vec::new(),
   42	            Some("query parameter q must not be empty".into()),
   43	        );
   44	    }
   45	
   46	    let runtime: Arc<AgentRuntime> = state.runtime.clone();
   47	    let search_query = query.clone();
   48	    match tokio::task::spawn_blocking(move || runtime.search_history(&search_query, params.limit))
   49	        .await
   50	    {
   51	        Ok(Ok(hits)) => response(StatusCode::OK, query, hits, None),
   52	        Ok(Err(error)) => {
   53	            tracing::warn!(error = %error, "history transcript search failed");
   54	            response(
   55	                StatusCode::INTERNAL_SERVER_ERROR,
   56	                query,
   57	                Vec::new(),
   58	                Some("transcript history could not be searched".into()),
   59	            )
   60	        }
   61	        Err(error) => {
   62	            tracing::warn!(error = %error, "history transcript search task failed");
   63	            response(
   64	                StatusCode::INTERNAL_SERVER_ERROR,
   65	                query,
   66	                Vec::new(),
   67	                Some("transcript history could not be searched".into()),
   68	            )
   69	        }
   70	    }
   71	}
