  573	            let squashed = entry.text.split_whitespace().collect::<Vec<_>>().join(" ");
  574	            let Some((match_kind, score, match_span)) = score_match(query, &squashed) else {
  575	                continue;
  576	            };
  577	            hits.push(HistorySearchHit {
  578	                hit_id: format!("{}:{message_index}", session.id),
  579	                session_id: session.id,
  580	                session_title: title.clone(),
  581	                role: entry.role,
  582	                excerpt: bounded_excerpt(&squashed, match_span),
  583	                timestamp_ms: entry.timestamp_ms,
  584	                workspace_root: session.workspace_root.clone(),
  585	                score,
  586	                match_kind,
  587	            });
  588	        }
  589	    }
  590	
  591	    hits.sort_by(|a, b| {
  592	        match_rank(b.match_kind)
  593	            .cmp(&match_rank(a.match_kind))
  594	            .then_with(|| b.score.total_cmp(&a.score))
  595	            .then_with(|| {
  596	                b.timestamp_ms
  597	                    .unwrap_or(0)
  598	                    .cmp(&a.timestamp_ms.unwrap_or(0))
  599	            })
  600	            .then_with(|| a.hit_id.cmp(&b.hit_id))
  601	    });
  602	    hits.truncate(limit);
  603	    Ok(hits)
  604	}
