  622	#[derive(Debug, Clone, Copy)]
  623	struct MatchSpan {
  624	    start: usize,
  625	    end: usize,
  626	}
  627	
  628	fn lexical_tokens(value: &str) -> Vec<(String, MatchSpan)> {
  629	    let mut tokens = Vec::new();
  630	    let mut token = String::new();
  631	    let mut start = 0usize;
  632	    let mut end = 0usize;
  633	    for (index, character) in value.chars().enumerate() {
  634	        if character.is_alphanumeric() {
  635	            if token.is_empty() {
  636	                start = index;
  637	            }
  638	            token.extend(character.to_lowercase());
  639	            end = index + 1;
  640	        } else if !token.is_empty() {
  641	            tokens.push((std::mem::take(&mut token), MatchSpan { start, end }));
  642	        }
  643	    }
  644	    if !token.is_empty() {
  645	        tokens.push((token, MatchSpan { start, end }));
  646	    }
  647	    tokens
  648	}
  649	
  650	fn folded_chars(value: &str, alphanumeric_only: bool) -> (Vec<char>, Vec<usize>) {
  651	    let mut folded = Vec::new();
  652	    let mut source_positions = Vec::new();
  653	    for (source_index, character) in value.chars().enumerate() {
  654	        if alphanumeric_only && !character.is_alphanumeric() {
  655	            continue;
  656	        }
  657	        for lowercase in character.to_lowercase() {
  658	            folded.push(lowercase);
  659	            source_positions.push(source_index);
  660	        }
  661	    }
  662	    (folded, source_positions)
  663	}
  664	
  665	fn score_match(query: &str, text: &str) -> Option<(HistoryMatchKind, f64, MatchSpan)> {
  666	    let normalized_query = normalized_phrase(query);
  667	    let (needle_phrase, _) = folded_chars(&normalized_query, false);
  668	    let (haystack_phrase, phrase_positions) = folded_chars(text, false);
  669	    if !needle_phrase.is_empty() {
  670	        if let Some(start) = haystack_phrase
  671	            .windows(needle_phrase.len())
  672	            .position(|window| window == needle_phrase)
  673	        {
  674	            let end = start + needle_phrase.len() - 1;
  675	            let ratio = needle_phrase.len() as f64 / haystack_phrase.len().max(1) as f64;
  676	            return Some((
  677	                HistoryMatchKind::Exact,
  678	                3.0 + ratio.min(1.0) * 0.5,
  679	                MatchSpan {
  680	                    start: phrase_positions[start],
  681	                    end: phrase_positions[end] + 1,
  682	                },
  683	            ));
  684	        }
  685	    }
  686	
  687	    let query_tokens = lexical_tokens(query);
  688	    let text_tokens = lexical_tokens(text);
  689	    let lexical_spans = query_tokens
  690	        .iter()
  691	        .map(|(query_token, _)| {
  692	            text_tokens
  693	                .iter()
  694	                .find(|(text_token, _)| text_token == query_token)
  695	                .map(|(_, span)| *span)
  696	        })
  697	        .collect::<Option<Vec<_>>>();
  698	    if !query_tokens.is_empty() {
  699	        if let Some(lexical_spans) = lexical_spans {
  700	            let ratio = query_tokens.len() as f64 / text_tokens.len().max(1) as f64;
  701	            return Some((
  702	                HistoryMatchKind::Lexical,
  703	                2.0 + ratio.min(1.0) * 0.5,
  704	                MatchSpan {
  705	                    start: lexical_spans.iter().map(|span| span.start).min().unwrap(),
  706	                    end: lexical_spans.iter().map(|span| span.end).max().unwrap(),
  707	                },
  708	            ));
  709	        }
  710	    }
  711	
  712	    let (needle, _) = folded_chars(query, true);
  713	    let (haystack, positions) = folded_chars(text, true);
  714	    if needle.is_empty() || haystack.is_empty() {
  715	        return None;
  716	    }
  717	    let mut matched = 0usize;
  718	    let mut start = 0usize;
  719	    for (index, character) in haystack.iter().enumerate() {
  720	        if *character == needle[matched] {
  721	            if matched == 0 {
  722	                start = index;
  723	            }
  724	            matched += 1;
  725	            if matched == needle.len() {
  726	                let span = index - start + 1;
  727	                let compactness = needle.len() as f64 / span as f64;
  728	                let coverage = needle.len() as f64 / haystack.len() as f64;
  729	                return Some((
  730	                    HistoryMatchKind::Fuzzy,
  731	                    1.0 + compactness * 0.75 + coverage.min(1.0) * 0.24,
  732	                    MatchSpan {
  733	                        start: positions[start],
  734	                        end: positions[index] + 1,
  735	                    },
  736	                ));
  737	            }
  738	        }
  739	    }
  740	    None
  741	}
  742	
  743	const HISTORY_EXCERPT_CHARS: usize = 240;
  744	
  745	fn bounded_excerpt(text: &str, match_span: MatchSpan) -> String {
  746	    let chars = text.chars().collect::<Vec<_>>();
  747	    if chars.len() <= HISTORY_EXCERPT_CHARS {
  748	        return text.to_string();
  749	    }
  750	
  751	    // Reserve room for both ellipses, then center the window on the match span.
  752	    // This stays Unicode-safe because every boundary is a character index.
  753	    let content_chars = HISTORY_EXCERPT_CHARS - 2;
  754	    let center = match_span.start + (match_span.end.saturating_sub(match_span.start) / 2);
  755	    let start = center
  756	        .saturating_sub(content_chars / 2)
  757	        .min(chars.len() - content_chars);
  758	    let end = start + content_chars;
  759	    let mut excerpt = String::new();
  760	    if start > 0 {
  761	        excerpt.push('…');
  762	    }
  763	    excerpt.extend(chars[start..end].iter());
  764	    if end < chars.len() {
  765	        excerpt.push('…');
  766	    }
  767	    excerpt
  768	}
